from PIL import Image, ImageDraw, ImageEnhance, ImageOps
import numpy as np
im = Image.open('radiograph.jpg').convert('RGB')
def gridcrop(name, x1,y1,x2,y2, scale=2, step=50, gamma=1.15, contrast=1.5):
    c = im.crop((x1,y1,x2,y2)).resize(((x2-x1)*scale,(y2-y1)*scale), Image.LANCZOS)
    if gamma!=1.0:
        a=np.asarray(c).astype(np.float32)/255; a=np.power(a,gamma)
        c=Image.fromarray((a*255).astype(np.uint8))
    c = ImageEnhance.Contrast(c).enhance(contrast)
    d = ImageDraw.Draw(c)
    for gx in range(x1//step*step+step, x2, step):
        X=(gx-x1)*scale; d.line([(X,0),(X,c.height)], fill=(255,0,0), width=1)
        if gx%100==0: d.text((X+2,2), str(gx), fill=(255,255,0))
    for gy in range(y1//step*step+step, y2, step):
        Y=(gy-y1)*scale; d.line([(0,Y),(c.width,Y)], fill=(0,120,255), width=1)
        if gy%100==0: d.text((2,Y+2), str(gy), fill=(0,255,255))
    c = ImageOps.autocontrast(c, cutoff=0.3)
    c.save(f'crops/{name}.png')
gridcrop('ur_ant_prem', 780, 340, 1300, 660)
gridcrop('ul_ant_prem', 1200, 340, 1650, 660)
print('ok')
EOF", "description": "Gridded crops of upper anterior-premolar segments"}
